import java.util.*;
import java.util.stream.*;

public class Main {
    record Student(String name, int score, int classId) {}

    public static void main(String[] args) {
        List<Student> ss = List.of(
            new Student("张三", 85, 1),
            new Student("李四", 92, 1),
            new Student("王五", 78, 2),
            new Student("赵六", 60, 2)
        );

        Map<Integer, Double> avg = ss.stream().collect(
            Collectors.groupingBy(Student::classId, Collectors.averagingDouble(Student::score)));
        System.out.println("班级均分: " + avg);

        String passed = ss.stream().filter(s -> s.score >= 80)
            .sorted(Comparator.comparingInt(Student::score).reversed())
            .map(Student::name).collect(Collectors.joining(", ", "[", "]"));
        System.out.println("及格名单: " + passed);
    }
}

