// Student.java
public class Student {
    private int id;
    private String name;
    private int score;
    public Student(int id, String name, int score) {
        this.id = id; this.name = name; this.score = score;
    }
    @Override public String toString() { return id + " | " + name + " | " + score; }
    // getter / setter
    public int getId() { return id; }
    public String getName() { return name; }
    public int getScore() { return score; }
    public void setName(String n) { this.name = n; }
    public void setScore(int s) { this.score = s; }
}

import java.sql.*;
import java.util.*;

public class StudentDaoImpl implements StudentDao {
    static final String URL = "jdbc:sqlite:sandbox.db";

    @Override
    public void insert(Student s) throws SQLException {
        String sql = "INSERT INTO students(name, class_id, gender, enrolled_at) VALUES (?, ?, 'M', ?)";
        try (Connection c = DriverManager.getConnection(URL);
             PreparedStatement ps = c.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
            ps.setString(1, s.getName());
            ps.setInt(2, 99);
            ps.setString(3, "2026-01-01");
            ps.executeUpdate();
            try (ResultSet keys = ps.getGeneratedKeys()) {
                if (keys.next()) /* s.setId(keys.getInt(1)) */;
            }
        }
    }

    @Override
    public List<Student> findAll() throws SQLException {
        List<Student> list = new ArrayList<>();
        try (Connection c = DriverManager.getConnection(URL);
             PreparedStatement ps = c.prepareStatement("SELECT id, name, score FROM students WHERE class_id = 99")) {
            try (ResultSet rs = ps.executeQuery()) {
                while (rs.next()) {
                    list.add(new Student(rs.getInt("id"), rs.getString("name"), rs.getInt("score")));
                }
            }
        }
        return list;
    }
}

public class Main {
    public static void main(String[] args) {
        // 1. 手机号: 1 开头,第二位 3-9,共 11 位数字
        String phone = "13812345678";
        System.out.println("手机号合法? " + phone.matches("1[3-9]\\d{9}"));

        // 2. 邮箱(简化版)
        String email = "learner@example.com";
        System.out.println("邮箱合法? " + email.matches("\\w+@[a-zA-Z0-9]+\\.[a-zA-Z]{2,}"));

        // 3. 密码强度: 至少 8 位,同时含字母和数字(用两次校验组合)
        String pwd = "abc12345";
        boolean ok = pwd.length() >= 8
                && pwd.matches(".*[a-zA-Z].*")
                && pwd.matches(".*\\d.*");
        System.out.println("密码强度合格? " + ok);

        // 4. 身份证校验: 18 位,末位可为 X
        String id = "11010119900307777X";
        System.out.println("身份证格式? " + id.matches("\\d{17}[\\dX]"));

        // 5. 纯中文判断
        System.out.println("纯中文? " + "张三".matches("[一-龥]+"));

        // 6. 常见错误示范: . 没转义,把 "1x2x3" 也放行了
