import java.util.regex.Pattern;

public class Main {

    /** 表单校验工具类: Pattern 预编译 + 静态方法 */
    static class Validators {
        private Validators() {} // 禁止实例化

        private static final Pattern PHONE = Pattern.compile("1[3-9]\\d{9}");
        private static final Pattern EMAIL = Pattern.compile("\\w+@[a-zA-Z0-9]+(\\.[a-zA-Z]{2,})+");
        private static final Pattern ID_CARD = Pattern.compile("\\d{17}[\\dXx]");
        private static final Pattern NUMBER = Pattern.compile("-?\\d+(\\.\\d+)?");

        public static boolean isPhone(String s)   { return s != null && PHONE.matcher(s).matches(); }
        public static boolean isEmail(String s)   { return s != null && EMAIL.matcher(s).matches(); }
        public static boolean isIdCard(String s)  { return s != null && ID_CARD.matcher(s).matches(); }
        public static boolean isNumber(String s)  { return s != null && NUMBER.matcher(s).matches(); }

        /** 强密码: 至少 8 位,含大写、小写、数字 */
        public static boolean isStrongPassword(String s) {
            return s != null && s.length() >= 8
                    && s.matches(".*[A-Z].*")
                    && s.matches(".*[a-z].*")
                    && s.matches(".*\\d.*");
        }
    }

    public static void main(String[] args) {
        // 模拟一次注册表单校验
        String[][] form = {
            {"手机号",   "13812345678",      String.valueOf(Validators.isPhone("13812345678"))},
            {"手机号错", "123456",           String.valueOf(Validators.isPhone("123456"))},
            {"邮箱",     "dev@workbuddy.cn", String.valueOf(Validators.isEmail("dev@workbuddy.cn"))},
            {"邮箱错",   "dev@",             String.valueOf(Validators.isEmail("dev@"))},
            {"密码",     "Java2026ok",       String.valueOf(Validators.isStrongPassword("Java2026ok"))},
            {"密码弱",   "12345678",         String.valueOf(Validators.isStrongPassword("12345678"))},
        };
        for (String[] row : form) {
            System.out.printf("%-8s %-18s -> %s%n", row[0], row[1], row[2]);
        }
    }
}

public class Main {

    /** 30 行迷你测试框架: JUnit 的思想内核 */
    static class MiniTest {
        static int passed = 0, failed = 0;

        static void assertEquals(Object expected, Object actual, String caseName) {
            if (expected.equals(actual)) {
                passed++;
                System.out.println("  PASS " + caseName);
            } else {
                failed++;
                System.out.println("  FAIL " + caseName
                        + " | 期望: " + expected + ", 实际: " + actual);
            }
        }

        static void assertTrue(boolean condition, String caseName) {
            assertEquals(true, condition, caseName);
        }

        static void report() {
            System.out.printf("%n结果: %d 通过, %d 失败%n", passed, failed);
        }
    }

    /** 被测对象: 计分器 */
    static class ScoreCalculator {
        /** 满分 100,平时分占 40%,考试占 60% */
        int total(int usual, int exam) {
            return (int) (usual * 0.4 + exam * 0.6);
        }
        boolean isPass(int totalScore) {
            return totalScore >= 60;
        }
    }

    public static void main(String[] args) {
        ScoreCalculator calc = new ScoreCalculator();

        System.out.println("--- 总分计算 ---");
        MiniTest.assertEquals(100, calc.total(100, 100), "双满分应为 100");
        // 下面这条预期故意写成 76(正确是 86),观察 FAIL 输出
        MiniTest.assertEquals(76, calc.total(80, 90), "80*0.4 + 90*0.6 = ?");
        MiniTest.assertEquals(0, calc.total(0, 0), "双零分应为 0");

        System.out.println("--- 及格判定(边界!) ---");
        MiniTest.assertTrue(calc.isPass(60), "60 分应及格(边界值)");
        MiniTest.assertTrue(!calc.isPass(59), "59 分不应及格(边界值-1)");

        MiniTest.report();
    }
}

import java.util.ArrayList;
