    }

    // ---- 以下模拟 JUnit 的组织方式(真实项目用 @Test + mvn test 运行) ----

    static Cart cart; // Fixture: 每个"测试"前重建,保证用例独立

    static void beforeEach() { cart = new Cart(); }

    static void testAddAndTotal() {
        beforeEach();
        cart.add(100); cart.add(200);
        check(cart.total() == 300 && cart.count() == 2, "加两件商品后总额 300、数量 2");
    }

    static void testEmptyCart() {
        beforeEach();
        check(cart.total() == 0, "空购物车总额为 0");
    }

    static void testNegativePriceThrows() {
        beforeEach();
        boolean thrown = false;
        try {
