import java.io.*;
import java.net.ServerSocket;
import java.net.Socket;
import java.nio.charset.StandardCharsets;

public class Main {
    public static void main(String[] args) {
        try {
            // 1. 启动回声服务器(独立线程)
            Thread server = new Thread(Main::echoServer, "回声服务器");
            server.start();
            Thread.sleep(200); // 等服务器就绪

            // 2. 客户端连接并发送三条消息
            try (Socket socket = new Socket("127.0.0.1", 18888);
                 BufferedWriter out = new BufferedWriter(new OutputStreamWriter(
                         socket.getOutputStream(), StandardCharsets.UTF_8));
                 BufferedReader in = new BufferedReader(new InputStreamReader(
                         socket.getInputStream(), StandardCharsets.UTF_8))) {

                String[] messages = {"hello", "java 网络编程", "bye"};
                for (String msg : messages) {
                    out.write(msg + "\n");
                    out.flush();
                    String echo = in.readLine();
                    System.out.println("客户端发送: " + msg + " -> 收到回声: " + echo);
                    if ("bye".equals(msg)) break;
                }
            }
            server.join(2000);
            System.out.println("通信结束");
        } catch (Exception e) {
            System.out.println("沙箱环境可能限制端口绑定: " + e.getMessage());
            System.out.println("请把代码复制到本地运行,效果相同");
        }
    }

    static void echoServer() {
        try (ServerSocket ss = new ServerSocket(18888)) {
            System.out.println("服务器启动,监听 18888...");
            try (Socket client = ss.accept(); // 阻塞等待客户端
                 BufferedReader in = new BufferedReader(new InputStreamReader(
                         client.getInputStream(), StandardCharsets.UTF_8));
                 BufferedWriter out = new BufferedWriter(new OutputStreamWriter(
                         client.getOutputStream(), StandardCharsets.UTF_8))) {
                System.out.println("客户端已连接: " + client.getInetAddress());
                String line;
                while ((line = in.readLine()) != null) {
                    System.out.println("服务器收到: " + line);
                    out.write("ECHO: " + line + "\n");
                    out.flush();
                    if ("bye".equals(line)) break;
                }
            }
        } catch (IOException e) {
            System.out.println("服务器异常: " + e.getMessage());
        }
    }
}

import java.net.DatagramPacket;
import java.net.DatagramSocket;
import java.net.InetAddress;
import java.nio.charset.StandardCharsets;

public class Main {
    public static void main(String[] args) {
        try {
            // UDP 接收端(无需 accept,直接 receive)
            Thread receiver = new Thread(() -> {
                try (DatagramSocket socket = new DatagramSocket(19999)) {
                    System.out.println("UDP 接收端就绪,端口 19999");
                    byte[] buf = new byte[1024];
                    DatagramPacket packet = new DatagramPacket(buf, buf.length);
                    socket.receive(packet); // 阻塞等包裹
                    String msg = new String(packet.getData(), 0, packet.getLength(),
                            StandardCharsets.UTF_8);
                    System.out.println("收到来自 " + packet.getAddress() + " 的包裹: " + msg);
                } catch (Exception e) {
                    System.out.println("接收端异常: " + e.getMessage());
                }
            });
            receiver.start();
            Thread.sleep(200);

            // UDP 发送端: 扔出去就完事,不管对方收没收到
            try (DatagramSocket sender = new DatagramSocket()) {
                String msg = "这是一条 UDP 消息,不需要握手!";
                byte[] data = msg.getBytes(StandardCharsets.UTF_8);
                DatagramPacket packet = new DatagramPacket(
                        data, data.length, InetAddress.getByName("127.0.0.1"), 19999);
                sender.send(packet);
                System.out.println("已发送 UDP 包裹(" + data.length + " 字节),发送方不等待确认");
            }

            receiver.join(2000);
        } catch (Exception e) {
            System.out.println("沙箱环境可能限制网络: " + e.getMessage());
            System.out.println("请复制代码到本地运行");
        }
    }
}

import com.sun.net.httpserver.HttpServer;
import java.io.OutputStream;
import java.net.InetSocketAddress;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;

public class Main {
    public static void main(String[] args) {
        HttpServer server = null;
        try {
            // 1. JDK 内置迷你 HTTP 服务器(教学用,生产别用)
            server = HttpServer.create(new InetSocketAddress("127.0.0.1", 17777), 0);
            server.createContext("/api/hello", exchange -> {
                String name = exchange.getRequestHeaders().getFirst("X-User");
                String body = "{\"message\":\"你好, " + (name == null ? "访客" : name) + "\"}";
                byte[] bytes = body.getBytes(StandardCharsets.UTF_8);
                exchange.getResponseHeaders().set("Content-Type", "application/json; charset=utf-8");
                exchange.sendResponseHeaders(200, bytes.length);
                try (OutputStream os = exchange.getResponseBody()) {
                    os.write(bytes);
                }
            });
            server.start();
            System.out.println("本地 HTTP 服务已启动: http://127.0.0.1:17777");

            // 2. HttpClient 同步 GET(带自定义 Header)
            HttpClient client = HttpClient.newHttpClient();
            HttpRequest getReq = HttpRequest.newBuilder()
                    .uri(URI.create("http://127.0.0.1:17777/api/hello"))
                    .header("X-User", "Zhang-San") // HTTP 头值必须是 ASCII,中文需先 URL 编码
                    .GET()
                    .build();
            HttpResponse<String> resp = client.send(getReq, HttpResponse.BodyHandlers.ofString());
            System.out.println("同步 GET -> " + resp.statusCode() + " " + resp.body());

            // 3. 异步 POST: CompletableFuture 链式处理
            HttpRequest postReq = HttpRequest.newBuilder()
                    .uri(URI.create("http://127.0.0.1:17777/api/hello"))
                    .header("Content-Type", "application/json")
                    .POST(HttpRequest.BodyPublishers.ofString("{\"course\":\"java\"}"))
                    .build();
            client.sendAsync(postReq, HttpResponse.BodyHandlers.ofString())
                    .thenApply(HttpResponse::body)
                    .thenAccept(body -> System.out.println("异步 POST -> " + body))
                    .join(); // 教学演示: 等待异步完成

            // 4. 访问真实外网请把 URI 换成 https://www.baidu.com(沙箱无外网,本地可用)
        } catch (Exception e) {
            System.out.println("沙箱环境可能限制网络: " + e.getMessage());
            System.out.println("请复制代码到本地运行");
        } finally {
            if (server != null) server.stop(0);
        }
    }
}

public class Main {

    // 1. 饿汉式: 类加载即创建
    static class EagerSingleton {
        private static final EagerSingleton INSTANCE = new EagerSingleton();
        private EagerSingleton() {}
        public static EagerSingleton getInstance() { return INSTANCE; }
    }

    // 2. 双重检查锁: volatile 防止指令重排导致拿到"半初始化"对象
    static class DclSingleton {
        private static volatile DclSingleton instance;
        private DclSingleton() {}
        public static DclSingleton getInstance() {
            if (instance == null) {                    // 第一次检查(无锁,快)
                synchronized (DclSingleton.class) {
                    if (instance == null) {            // 第二次检查(持锁,准)
                        instance = new DclSingleton();
                    }
                }
            }
            return instance;
        }
    }

    // 3. 静态内部类: 类加载机制保证线程安全 + 懒加载
    static class HolderSingleton {
        private HolderSingleton() {}
        private static class Holder {
            static final HolderSingleton INSTANCE = new HolderSingleton();
        }
        public static HolderSingleton getInstance() { return Holder.INSTANCE; }
    }

    // 4. 枚举单例: 终极答案(防反射、防序列化)
    enum EnumSingleton {
        INSTANCE;
        public void hello() { System.out.println("枚举单例: 我是唯一!"); }
    }

    public static void main(String[] args) throws InterruptedException {
        // 多线程并发获取,验证都是同一实例
        Object[] results = new Object[10];
        Thread[] ts = new Thread[10];
        for (int i = 0; i < 10; i++) {
            int idx = i;
            ts[i] = new Thread(() -> results[idx] = DclSingleton.getInstance());
            ts[i].start();
        }
        for (Thread t : ts) t.join();

        boolean allSame = true;
        for (int i = 1; i < results.length; i++) {
            if (results[i] != results[0]) allSame = false;
        }
        System.out.println("DCL 单例: 10 个线程拿到同一实例? " + allSame);
        System.out.println("饿汉式 identityHash: " + System.identityHashCode(EagerSingleton.getInstance()));
        System.out.println("内部类 identityHash: " + System.identityHashCode(HolderSingleton.getInstance()));
        EnumSingleton.INSTANCE.hello();
    }
}

import java.util.HashMap;
import java.util.Map;
import java.util.function.Supplier;

public class Main {

    // ---- 产品族: 支付接口与实现 ----
    interface Pay {
        void pay(int amount);
    }
    static class WechatPay implements Pay {
        public void pay(int amount) { System.out.println("微信支付 " + amount + " 元"); }
    }
    static class Alipay implements Pay {
        public void pay(int amount) { System.out.println("支付宝支付 " + amount + " 元"); }
    }

    // ---- 简单工厂: switch 版(新增类型要改这里) ----
    static class SimplePayFactory {
        static Pay create(String type) {
            return switch (type) {
                case "wechat" -> new WechatPay();
                case "alipay" -> new Alipay();
                default -> throw new IllegalArgumentException("未知支付: " + type);
            };
        }
    }

    // ---- 注册表工厂: Map + Supplier(新增类型只需注册,不改工厂) ----
    static class PayRegistry {
        private static final Map<String, Supplier<Pay>> REGISTRY = new HashMap<>();
        static void register(String type, Supplier<Pay> supplier) {
            REGISTRY.put(type, supplier);
        }
        static Pay create(String type) {
            Supplier<Pay> s = REGISTRY.get(type);
            if (s == null) throw new IllegalArgumentException("未注册的支付: " + type);
            return s.get();
        }
    }

    public static void main(String[] args) {
        // 初始化注册
        PayRegistry.register("wechat", WechatPay::new);
        PayRegistry.register("alipay", Alipay::new);

        // 使用方完全不知道具体类
        PayRegistry.create("wechat").pay(100);
        SimplePayFactory.create("alipay").pay(200);

        // 扩展演示: 新增"云闪付",注册表一行搞定,工厂代码零修改!
        class UnionPay implements Pay {
            public void pay(int amount) { System.out.println("云闪付支付 " + amount + " 元"); }
        }
        PayRegistry.register("unionpay", UnionPay::new);
        PayRegistry.create("unionpay").pay(300);

        System.out.println("对照思考: Spring 的 @Service 注解 = register,getBean = create");
    }
}

import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CopyOnWriteArrayList;

public class Main {

    /** 事件对象 */
    record OrderEvent(String orderId, int amount, String user) {}

    /** 监听器接口(观察者) */
    interface EventListener<T> {
        void onEvent(T event);
    }

    /** 迷你事件总线(发布-订阅,双方互不相识) */
    static class EventBus {
        // CopyOnWriteArrayList: 读多写少,遍历时注册新监听器也安全
        private final Map<Class<?>, List<EventListener<?>>> listeners = new ConcurrentHashMap<>();

        <T> void subscribe(Class<T> eventType, EventListener<T> listener) {
            listeners.computeIfAbsent(eventType, k -> new CopyOnWriteArrayList<>()).add(listener);
        }

        @SuppressWarnings("unchecked")
        <T> void publish(T event) {
            List<EventListener<?>> list = listeners.getOrDefault(event.getClass(), List.of());
            for (EventListener<?> l : list) {
                ((EventListener<T>) l).onEvent(event);
            }
        }
    }

    public static void main(String[] args) {
        EventBus bus = new EventBus();

        // 三个监听器各自订阅,互不知道对方存在
        bus.subscribe(OrderEvent.class, e ->
                System.out.println("[积分服务] 用户 " + e.user() + " 获得 " + e.amount() + " 积分"));
        bus.subscribe(OrderEvent.class, e ->
                System.out.println("[库存服务] 订单 " + e.orderId() + " 锁定库存"));
        bus.subscribe(OrderEvent.class, e ->
                System.out.println("[消息服务] 给用户 " + e.user() + " 发送下单成功通知"));

        // 业务代码只负责发布事件——一行搞定,不关心谁在处理
        System.out.println("--- 用户下单 ---");
        bus.publish(new OrderEvent("NO-10086", 299, "小明"));

        System.out.println("--- 又一个订单 ---");
        bus.publish(new OrderEvent("NO-10087", 59, "小红"));

        System.out.println("对照思考: Spring 的 publishEvent + @EventListener 就是这个 EventBus");
    }
}

import java.util.HashMap;
import java.util.Map;

public class Main {

    /** 策略接口: 满减折扣算法(函数式接口,Lambda 可直接当策略) */
    @FunctionalInterface
    interface Discount {
        int apply(int originalPrice);
    }

    /** 策略注册表: 策略名 -> 策略实现 */
    static final Map<String, Discount> STRATEGIES = new HashMap<>();
    static {
        STRATEGIES.put("原价",   p -> p);
        STRATEGIES.put("九折",   p -> p * 90 / 100);
        STRATEGIES.put("满300减50", p -> p >= 300 ? p - 50 : p);
        STRATEGIES.put("VIP折上折", p -> (int) (p * 0.8 * 0.95));
    }

    /** 结算上下文: 持有并执行策略 */
    static int checkout(String strategyName, int price) {
        Discount d = STRATEGIES.get(strategyName);
        if (d == null) throw new IllegalArgumentException("未知策略: " + strategyName);
        return d.apply(price);
    }

    public static void main(String[] args) {
        int price = 500;
        System.out.println("原价 " + price + " 元,各策略结算价:");
        STRATEGIES.forEach((name, d) ->
                System.out.printf("  %-10s -> %d 元%n", name, d.apply(price)));

        // 运行时切换策略(比如根据用户等级)
        String userLevel = "VIP";
        String chosen = userLevel.equals("VIP") ? "VIP折上折" : "九折";
        System.out.println("VIP 用户实际支付: " + checkout(chosen, price) + " 元");

        // 扩展演示: 新增"第二件半价"策略 = 注册一行,老代码零修改
        STRATEGIES.put("第二件半价", p -> p - p / 4); // 假设两件同价商品
        System.out.println("新策略[第二件半价] -> " + checkout("第二件半价", price) + " 元");

        System.out.println("反面对照: 用 if-else 写,每加一个策略就要改结算方法,规则多了必失控");
    }
}

public class Main {

    /** 组件接口 */
    interface Coffee {
        String description();
        int cost();
    }

    /** 具体组件: 美式咖啡 */
    static class Americano implements Coffee {
        public String description() { return "美式咖啡"; }
        public int cost() { return 20; }
    }

    /** 装饰器基类: 实现同一接口,持有被装饰者 */
    static abstract class CoffeeDecorator implements Coffee {
        protected final Coffee coffee;
        CoffeeDecorator(Coffee coffee) { this.coffee = coffee; }
    }

    static class Milk extends CoffeeDecorator {
        Milk(Coffee c) { super(c); }
        public String description() { return coffee.description() + " + 牛奶"; }
        public int cost() { return coffee.cost() + 5; }
    }

    static class Sugar extends CoffeeDecorator {
        Sugar(Coffee c) { super(c); }
        public String description() { return coffee.description() + " + 糖"; }
        public int cost() { return coffee.cost() + 2; }
    }

    static class Ice extends CoffeeDecorator {
        Ice(Coffee c) { super(c); }
        public String description() { return coffee.description() + " + 加冰"; }
        public int cost() { return coffee.cost() + 0; }
