}

public class Main {

    /** 审批请求 */
    record LeaveRequest(String employee, int days, String reason) {}

    /** 责任链 + 模板方法: 审批人抽象 */
    static abstract class Approver {
        protected Approver next; // 链条上的下一棒

        Approver setNext(Approver next) { this.next = next; return next; }

        /** 模板方法: 固定处理骨架,子类只实现"能否批"和"怎么批" */
        final void handle(LeaveRequest req) {
            if (canApprove(req)) {
                doApprove(req); // 可变步骤 1
            } else if (next != null) {
                System.out.println("  " + name() + ": 权限不足(" + maxDays() + "天),上报上级");
                next.handle(req); // 传给下一棒
            } else {
                System.out.println("  " + name() + ": 链条到头,没人能批,拒绝!");
            }
        }

        abstract boolean canApprove(LeaveRequest req); // 可变步骤 2
        abstract int maxDays();
        abstract String name();

        void doApprove(LeaveRequest req) {
            System.out.println("  " + name() + ": 批准 " + req.employee()
                    + " 请假 " + req.days() + " 天(" + req.reason() + ")");
        }
    }

    static class TeamLeader extends Approver {
        boolean canApprove(LeaveRequest r) { return r.days() <= 2; }
        int maxDays() { return 2; }
        String name() { return "组长"; }
    }
    static class Manager extends Approver {
        boolean canApprove(LeaveRequest r) { return r.days() <= 5; }
        int maxDays() { return 5; }
        String name() { return "经理"; }
    }
    static class Director extends Approver {
        boolean canApprove(LeaveRequest r) { return r.days() <= 15; }
        int maxDays() { return 15; }
        String name() { return "总监"; }
    }

    public static void main(String[] args) {
        // 组装责任链: 组长 -> 经理 -> 总监
        Approver chain = new TeamLeader();
        chain.setNext(new Manager()).setNext(new Director());

        LeaveRequest[] requests = {
            new LeaveRequest("小王", 1, "家里有事"),
            new LeaveRequest("小李", 4, "年假旅行"),
            new LeaveRequest("小张", 10, "婚假"),
            new LeaveRequest("老周", 30, "环球旅行"),
        };
        for (LeaveRequest r : requests) {
            System.out.println("申请: " + r.employee() + " 请假 " + r.days() + " 天");
            chain.handle(r);
        }
        System.out.println("对照思考: Servlet 的 FilterChain、Spring 拦截器链都是这个模式");
    }
}

import java.net.URLDecoder;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.Base64;

public class Main {
    public static void main(String[] args) throws Exception {
        // 1. Base64 编解码(编码,不是加密!)
        String secret = "我的密码abc123";
        String encoded = Base64.getEncoder()
                .encodeToString(secret.getBytes(StandardCharsets.UTF_8));
        System.out.println("原文:   " + secret);
        System.out.println("Base64: " + encoded);

        String decoded = new String(Base64.getDecoder().decode(encoded), StandardCharsets.UTF_8);
        System.out.println("解回:   " + decoded);
        System.out.println("> 任何人都能解回 -> Base64 只是编码,毫无保密性!");

        // 2. Base64 在 HTTP Basic 认证中的用法(用户名:密码)
        String credential = "admin:admin123";
        String basicAuth = Base64.getEncoder()
                .encodeToString(credential.getBytes(StandardCharsets.UTF_8));
        System.out.println("\nBasic 认证头: Authorization: Basic " + basicAuth);

        // 3. URL 编码: 中文与特殊字符必须转义
        String keyword = "Java 学习 & 实战";
        String urlEncoded = URLEncoder.encode(keyword, StandardCharsets.UTF_8);
        System.out.println("\nURL 编码: " + urlEncoded);
        System.out.println("URL 解码: " + URLDecoder.decode(urlEncoded, StandardCharsets.UTF_8));

        // 4. 不是所有空格都变加号: 路径段与查询参数的规则略有差异
        System.out.println("\n空格编码为 + 或 %20,取决于上下文(查询参数常用 +,路径用 %20)");
    }
}

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.SecureRandom;
import java.util.HexFormat;

public class Main {

    /** 计算哈希(十六进制字符串) */
    static String hash(String algorithm, String input) throws Exception {
        MessageDigest md = MessageDigest.getInstance(algorithm);
        byte[] digest = md.digest(input.getBytes(StandardCharsets.UTF_8));
        return HexFormat.of().formatHex(digest);
    }

    public static void main(String[] args) throws Exception {
        String password = "admin123";

        // 1. 直接哈希: 相同密码 -> 相同结果,彩虹表可直接命中
        String md5 = hash("MD5", password);
        String sha256 = hash("SHA-256", password);
        System.out.println("MD5('admin123')    = " + md5);
        System.out.println("SHA256('admin123') = " + sha256);
        System.out.println("> 这两个值是公开的,搜索引擎一查就知道原文!\n");

        // 2. 加盐: 每个用户独立随机盐,结果完全不同
        byte[] salt1 = new byte[16], salt2 = new byte[16];
        new SecureRandom().nextBytes(salt1);
        new SecureRandom().nextBytes(salt2);
        System.out.println("用户A 加盐哈希: " + hashWithSalt(password, salt1));
        System.out.println("用户B 加盐哈希: " + hashWithSalt(password, salt2));
        System.out.println("> 同一个密码,两次结果不同 -> 彩虹表失效\n");

        // 3. 加盐 + 迭代(慢哈希): 暴力破解成本成倍上升
        long begin = System.currentTimeMillis();
        String slow = slowHash(password, salt1, 20000);
        long cost = System.currentTimeMillis() - begin;
        System.out.println("迭代 20000 次结果: " + slow.substring(0, 32) + "...");
        System.out.println("单次计算耗时 " + cost + "ms -> 破解成本被放大数万倍");
        System.out.println("\n生产建议: 用 BCrypt/PBKDF2/Argon2,别自己拼盐和迭代");
    }

    static String hashWithSalt(String password, byte[] salt) throws Exception {
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        md.update(salt);                                            // 先混入盐
        return HexFormat.of().formatHex(md.digest(password.getBytes(StandardCharsets.UTF_8)));
    }

    static String slowHash(String password, byte[] salt, int iterations) throws Exception {
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        byte[] data = password.getBytes(StandardCharsets.UTF_8);
        for (int i = 0; i < iterations; i++) {
            md.reset();
            md.update(salt);
            md.update(data);
            data = md.digest();
        }
        return HexFormat.of().formatHex(data);
    }
}

import java.nio.charset.StandardCharsets;
import java.security.SecureRandom;
import java.util.Base64;
import javax.crypto.Cipher;
import javax.crypto.KeyGenerator;
import javax.crypto.SecretKey;
import javax.crypto.spec.IvParameterSpec;

public class Main {
    public static void main(String[] args) throws Exception {
        String plainText = "用户手机号: 13812345678";

        // 1. 生成 AES 密钥(实际项目中安全保存,绝不硬编码!)
        KeyGenerator kg = KeyGenerator.getInstance("AES");
        kg.init(128);
        SecretKey key = kg.generateKey();
        System.out.println("AES 密钥(Base64): " + Base64.getEncoder().encodeToString(key.getEncoded()));

        // 2. 生成随机 IV(16 字节)
        byte[] iv = new byte[16];
        new SecureRandom().nextBytes(iv);

        // 3. 加密
        Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
        cipher.init(Cipher.ENCRYPT_MODE, key, new IvParameterSpec(iv));
        byte[] encrypted = cipher.doFinal(plainText.getBytes(StandardCharsets.UTF_8));
        String cipherText = Base64.getEncoder().encodeToString(encrypted);
        String ivBase64 = Base64.getEncoder().encodeToString(iv);
        System.out.println("\n密文(Base64): " + cipherText);
        System.out.println("IV(Base64):   " + ivBase64);

        // 4. 同样明文再加密一次 -> 密文不同(因为 IV 随机)
        byte[] iv2 = new byte[16];
        new SecureRandom().nextBytes(iv2);
        cipher.init(Cipher.ENCRYPT_MODE, key, new IvParameterSpec(iv2));
        String cipherText2 = Base64.getEncoder()
                .encodeToString(cipher.doFinal(plainText.getBytes(StandardCharsets.UTF_8)));
        System.out.println("\n同一明文第二次加密: " + cipherText2);
        System.out.println("> 密文不同,攻击者无法通过密文比对猜测内容\n");

        // 5. 解密(IV 必须与加密时一致)
        cipher.init(Cipher.DECRYPT_MODE, key, new IvParameterSpec(iv));
        byte[] decrypted = cipher.doFinal(Base64.getDecoder().decode(cipherText));
        System.out.println("解密还原: " + new String(decrypted, StandardCharsets.UTF_8));

        System.out.println("\n生产建议: 用 AES/GCM/NoPadding(GCM 自带防篡改),别用 ECB");
    }
}

import java.nio.charset.StandardCharsets;
import java.security.KeyPair;
import java.security.KeyPairGenerator;
import java.security.Signature;
import java.util.Base64;

public class Main {
    public static void main(String[] args) throws Exception {
        // 1. 生成 RSA 密钥对(演示用 1024 位;生产建议 2048 以上)
        KeyPairGenerator kpg = KeyPairGenerator.getInstance("RSA");
        kpg.initialize(1024);
        KeyPair keyPair = kpg.generateKeyPair();
        System.out.println("密钥对已生成: " + keyPair.getPublic().getAlgorithm()
                + " " + keyPair.getPublic().getEncoded().length * 8 + " 位(公钥)");

        String message = "转账 100 元给张三,订单号 NO-9527";

        // 2. 用私钥签名
        Signature signer = Signature.getInstance("SHA256withRSA");
        signer.initSign(keyPair.getPrivate());
        signer.update(message.getBytes(StandardCharsets.UTF_8));
        byte[] signature = signer.sign();
        String signatureB64 = Base64.getEncoder().encodeToString(signature);
        System.out.println("\n原文: " + message);
        System.out.println("签名(前 40 字符): " + signatureB64.substring(0, 40) + "...");

        // 3. 用公钥验证(任何人拿公钥都能验)
        Signature verifier = Signature.getInstance("SHA256withRSA");
        verifier.initVerify(keyPair.getPublic());
        verifier.update(message.getBytes(StandardCharsets.UTF_8));
        System.out.println("\n验证原始消息: " + (verifier.verify(signature) ? "通过 ✓" : "失败 ✗"));

        // 4. 篡改消息 -> 验证失败(这就是"防篡改")
        String tampered = "转账 10000 元给张三,订单号 NO-9527";
        Signature verifier2 = Signature.getInstance("SHA256withRSA");
        verifier2.initVerify(keyPair.getPublic());
        verifier2.update(tampered.getBytes(StandardCharsets.UTF_8));
        System.out.println("验证被篡改的消息: " + (verifier2.verify(signature) ? "通过 ✓" : "失败 ✗"));
        System.out.println("> 金额从 100 改成 10000,签名立刻失效\n");

        System.out.println("HTTPS 类比: 服务器证书 = 公钥 + CA 签名;");
        System.out.println("客户端验证 CA 签名 -> 确认服务器身份 -> 再协商会话密钥");
    }
}

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public class Main {

    /** 迷你 JSON 工具: 只支持 Map/List/String/Number/Boolean/null(教学版) */
    static class MiniJson {

        // ---------- 序列化 ----------
        static String toJson(Object o) {
            StringBuilder sb = new StringBuilder();
            write(sb, o);
            return sb.toString();
        }

        @SuppressWarnings("unchecked")
        private static void write(StringBuilder sb, Object o) {
            if (o == null) { sb.append("null"); return; }
            if (o instanceof String s) { sb.append('"').append(escape(s)).append('"'); return; }
            if (o instanceof Number || o instanceof Boolean) { sb.append(o); return; }
            if (o instanceof Map<?, ?> map) {
                sb.append('{');
                boolean first = true;
                for (Map.Entry<?, ?> e : map.entrySet()) {
                    if (!first) sb.append(',');
                    first = false;
                    sb.append('"').append(escape(String.valueOf(e.getKey()))).append("\":");
                    write(sb, e.getValue());
                }
                sb.append('}');
                return;
            }
            if (o instanceof List<?> list) {
                sb.append('[');
                for (int i = 0; i < list.size(); i++) {
                    if (i > 0) sb.append(',');
                    write(sb, list.get(i));
                }
                sb.append(']');
                return;
            }
            // 其他类型(如自定义对象)降级为字符串
            sb.append('"').append(escape(o.toString())).append('"');
        }

        private static String escape(String s) {
            return s.replace("\\", "\\\\").replace("\"", "\\\"")
                    .replace("\n", "\\n").replace("\t", "\\t");
        }

        // ---------- 反序列化 ----------
        static Object parse(String json) {
            return new Parser(json).parseValue();
        }

        static class Parser {
            final String s; int i = 0;
            Parser(String s) { this.s = s; }
            void ws() { while (i < s.length() && Character.isWhitespace(s.charAt(i))) i++; }

            Object parseValue() {
                ws();
                char c = s.charAt(i);
                return switch (c) {
                    case '{' -> parseObject();
                    case '[' -> parseArray();
                    case '"' -> parseString();
                    case 't' -> { i += 4; yield Boolean.TRUE; }
                    case 'f' -> { i += 5; yield Boolean.FALSE; }
                    case 'n' -> { i += 4; yield null; }
                    default  -> parseNumber();
                };
            }

            Map<String, Object> parseObject() {
                Map<String, Object> map = new LinkedHashMap<>();
                i++; // {
                ws();
                if (s.charAt(i) == '}') { i++; return map; }
                while (true) {
                    ws();
                    String key = parseString();
                    ws(); i++; // :
                    map.put(key, parseValue());
                    ws();
                    if (s.charAt(i) == ',') { i++; continue; }
                    i++; // }
                    return map;
                }
            }

            List<Object> parseArray() {
                List<Object> list = new ArrayList<>();
                i++; // [
                ws();
                if (s.charAt(i) == ']') { i++; return list; }
                while (true) {
                    list.add(parseValue());
                    ws();
                    if (s.charAt(i) == ',') { i++; continue; }
                    i++; // ]
                    return list;
                }
            }

            String parseString() {
                StringBuilder sb = new StringBuilder();
                i++; // 开引号
                while (s.charAt(i) != '"') {
                    char c = s.charAt(i);
                    if (c == '\\') {
                        i++;
                        char esc = s.charAt(i);
                        sb.append(switch (esc) {
                            case 'n' -> '\n'; case 't' -> '\t';
                            case 'r' -> '\r'; case '"' -> '"';
                            case '\\' -> '\\'; default -> esc;
                        });
                    } else sb.append(c);
                    i++;
                }
                i++; // 闭引号
                return sb.toString();
            }

            Object parseNumber() {
                int start = i;
                while (i < s.length() && "-+.eE0123456789".indexOf(s.charAt(i)) >= 0) i++;
                String num = s.substring(start, i);
                return num.contains(".") || num.contains("e") || num.contains("E")
                        ? (Object) Double.parseDouble(num) : (Object) Long.parseLong(num);
            }
        }
    }

    public static void main(String[] args) {
        // 1. 序列化: 嵌套结构
        Map<String, Object> user = new LinkedHashMap<>();
        user.put("id", 1001);
        user.put("name", "张三");
        user.put("vip", true);
        user.put("tags", List.of("Java", "后端"));
        user.put("address", Map.of("city", "深圳", "zip", "518000"));

        String json = MiniJson.toJson(user);
        System.out.println("序列化结果:");
        System.out.println("  " + json);

        // 2. 反序列化: 还原为 Map/List
        Object parsed = MiniJson.parse(json);
        System.out.println("\n反序列化类型: " + parsed.getClass().getSimpleName());
        @SuppressWarnings("unchecked")
        Map<String, Object> back = (Map<String, Object>) parsed;
        System.out.println("  name = " + back.get("name") + " (" + back.get("name").getClass().getSimpleName() + ")");
        System.out.println("  id   = " + back.get("id") + " (" + back.get("id").getClass().getSimpleName() + ")");
        System.out.println("  tags = " + back.get("tags"));

        // 3. 转义测试
        String tricky = MiniJson.toJson(Map.of("msg", "他说:\"你好\"\n换行了"));
        System.out.println("\n转义测试: " + tricky);
        System.out.println("解析回来: " + ((Map<?, ?>) MiniJson.parse(tricky)).get("msg"));
    }
}

import java.io.ByteArrayInputStream;
import java.nio.charset.StandardCharsets;
import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.NodeList;

public class Main {
    public static void main(String[] args) throws Exception {
        String xml = """
                <?xml version="1.0" encoding="UTF-8"?>
                <class name="Java 一班">
                    <student id="1001">
                        <name>张三</name>
                        <score>92</score>
                    </student>
                    <student id="1002">
                        <name>李四</name>
                        <score>78</score>
                    </student>
                    <student id="1003">
                        <name>王五</name>
                        <score>85</score>
                    </student>
                </class>
                """;

        // 1. 创建解析器(生产环境务必禁用 DTD 防 XXE 攻击)
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        try {
            factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        } catch (Exception ignore) { }
        DocumentBuilder builder = factory.newDocumentBuilder();

        // 2. 解析为 DOM 树
        Document doc = builder.parse(new ByteArrayInputStream(xml.getBytes(StandardCharsets.UTF_8)));
        Element root = doc.getDocumentElement();
        System.out.println("根元素: " + root.getTagName()
                + " (name=" + root.getAttribute("name") + ")");

        // 3. 遍历节点
        NodeList students = doc.getElementsByTagName("student");
        System.out.println("\n共 " + students.getLength() + " 名学生:");
        int total = 0, max = 0;
        String topName = "";
        for (int i = 0; i < students.getLength(); i++) {
            Element student = (Element) students.item(i);
            String id = student.getAttribute("id");
            Element nameEl = (Element) student.getElementsByTagName("name").item(0);
            Element scoreEl = (Element) student.getElementsByTagName("score").item(0);
            int score = Integer.parseInt(scoreEl.getTextContent());
            total += score;
            if (score > max) { max = score; topName = nameEl.getTextContent(); }
            System.out.printf("  学号 %s | %s | %d 分%n", id, nameEl.getTextContent(), score);
        }
        System.out.printf("%n平均分: %.1f,最高分: %s (%d)%n",
                (double) total / students.getLength(), topName, max);

        System.out.println("\n对照: pom.xml、Spring 老配置文件的解析就是这样进行的");
    }
}

import java.lang.reflect.Field;
import java.util.LinkedHashMap;
import java.util.Map;

public class Main {

    /** 模拟 Jackson 的行为: 按注解规则把对象转成 JSON(简化版) */
    static class User {
        Long id;
        String userName;              // Java 驼峰
        String passwordHash;          // 敏感,不序列化
        String email;
        String nickname;              // null,不输出

        User(Long id, String userName, String passwordHash, String email) {
            this.id = id; this.userName = userName;
            this.passwordHash = passwordHash; this.email = email;
        }
    }

    /** 极简"序列化器": 按规则挑字段 */
    static String serialize(Object obj) throws Exception {
        Map<String, Object> map = new LinkedHashMap<>();
        for (Field f : obj.getClass().getDeclaredFields()) {
            f.setAccessible(true);
            Object value = f.get(obj);

            // 规则1: 密码类字段忽略(对照 @JsonIgnore)
            if (f.getName().toLowerCase().contains("password")) continue;
            // 规则2: null 不输出(对照 @JsonInclude(NON_NULL))
            if (value == null) continue;
            // 规则3: 驼峰转下划线(对照 @JsonProperty)
            String key = camelToSnake(f.getName());
            map.put(key, value);
        }
        // 拼接 JSON
        StringBuilder sb = new StringBuilder("{");
        boolean first = true;
        for (Map.Entry<String, Object> e : map.entrySet()) {
            if (!first) sb.append(',');
            first = false;
            Object v = e.getValue();
            sb.append('"').append(e.getKey()).append("\":");
            sb.append(v instanceof Number ? v : "\"" + v + "\"");
        }
        return sb.append('}').toString();
    }

    static String camelToSnake(String s) {
        StringBuilder sb = new StringBuilder();
        for (char c : s.toCharArray()) {
            if (Character.isUpperCase(c)) sb.append('_').append(Character.toLowerCase(c));
            else sb.append(c);
        }
        return sb.toString();
    }

    public static void main(String[] args) throws Exception {
        User user = new User(1001L, "zhangsan", "$2a$10$abcdef...", "zs@example.com");

        System.out.println("原始字段: id / userName / passwordHash / email / nickname(null)");
        System.out.println("序列化结果:");
        System.out.println("  " + serialize(user));

        System.out.println("\n关键点:");
        System.out.println("  1. userName -> user_name (驼峰转下划线,对照 @JsonProperty)");
        System.out.println("  2. passwordHash 消失 (对照 @JsonIgnore,安全要点!)");
        System.out.println("  3. nickname 为 null 不输出 (对照 @JsonInclude(NON_NULL))");
        System.out.println("  4. 真实项目用 Jackson: objectMapper.writeValueAsString(user)");

        System.out.println("\n本项目实践: Controller 返回 Result.ok(data),Spring 自动完成上述序列化");
    }
}

import com.sun.net.httpserver.HttpServer;
import java.io.*;
import java.net.InetSocketAddress;
import java.net.Socket;
import java.nio.charset.StandardCharsets;

public class Main {
    public static void main(String[] args) {
        // 网络演示放入守护线程并限时等待: 环境限制网络时也不会卡住
        Thread demo = new Thread(Main::runDemo, "http-demo");
        demo.setDaemon(true);
        demo.start();
        try {
            demo.join(3000);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        if (demo.isAlive()) {
            System.out.println("\n[提示] 当前环境限制了本地端口/网络访问,演示未完成");
            System.out.println("请把代码复制到本地 IDE 运行,效果相同");
        }
    }

    static void runDemo() {
        HttpServer server = null;
        try {
            // 1. 启动一个迷你 HTTP 服务器 /api/hello
            server = HttpServer.create(new InetSocketAddress("127.0.0.1", 18080), 0);
            server.createContext("/api/hello", exchange -> {
                System.out.println("--- 服务器收到的请求 ---");
                System.out.println(exchange.getRequestMethod() + " " + exchange.getRequestURI());
                exchange.getRequestHeaders().forEach((k, v) ->
                        System.out.println(k + ": " + String.join(",", v)));
                String body = "{\"code\":0,\"message\":\"success\",\"data\":\"Hello HTTP\"}";
                byte[] bytes = body.getBytes(StandardCharsets.UTF_8);
                exchange.getResponseHeaders().set("Content-Type", "application/json; charset=utf-8");
                exchange.sendResponseHeaders(200, bytes.length);
                try (OutputStream os = exchange.getResponseBody()) { os.write(bytes); }
            });
            server.start();
            Thread.sleep(200);

            // 2. 用原始 Socket 手工发一段 HTTP 请求文本
            try (Socket socket = new Socket("127.0.0.1", 18080);
                 BufferedWriter out = new BufferedWriter(new OutputStreamWriter(
                         socket.getOutputStream(), StandardCharsets.UTF_8))) {
                out.write("GET /api/hello HTTP/1.1\r\n");
                out.write("Host: 127.0.0.1:18080\r\n");
                out.write("Authorization: Bearer my-token-123\r\n");
                out.write("User-Agent: LearningClient/1.0\r\n");
                out.write("\r\n"); // 空行表示请求头结束
                out.flush();

                System.out.println("\n--- 服务器返回的响应 ---");
                try (BufferedReader in = new BufferedReader(new InputStreamReader(
                        socket.getInputStream(), StandardCharsets.UTF_8))) {
                    String line;
                    int count = 0;
                    while ((line = in.readLine()) != null && count++ < 8) {
                        System.out.println(line);
                    }
                }
            }
        } catch (Exception e) {
            System.out.println("沙箱环境可能限制端口绑定: " + e.getMessage());
            System.out.println("请复制到本地运行");
        } finally {
            if (server != null) server.stop(0);
        }
    }
}

import com.sun.net.httpserver.HttpServer;
import java.io.OutputStream;
import java.net.InetSocketAddress;
import java.nio.charset.StandardCharsets;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;

public class Main {

    /** 迷你 Servlet 抽象: 对应 javax.servlet.Servlet 接口 */
    interface MiniServlet {
        default void init() { System.out.println("  [容器] " + getClass().getSimpleName() + ".init() 只调用一次"); }
        void service(String path, String method); // 不抛受检异常,便于在 lambda 内调用
        default void destroy() { System.out.println("  [容器] " + getClass().getSimpleName() + ".destroy() 容器关闭时调用"); }
    }

    static class HelloServlet implements MiniServlet {
        // 注意: 下面这个计数器展示"单例多线程"——真实开发不要这样存请求状态
        private int callCount = 0;
        public void service(String path, String method) {
            synchronized (this) { callCount++; }
            System.out.println("  [Servlet] 处理请求 " + method + " " + path
                    + " (第 " + callCount + " 次调用, 线程: " + Thread.currentThread().getName() + ")");
        }
    }

    public static void main(String[] args) throws Exception {
        // 1. 容器启动: 注册 Servlet 并初始化
        Map<String, MiniServlet> mappings = new ConcurrentHashMap<>();
        HelloServlet hello = new HelloServlet();
        hello.init(); // 生命周期: 只初始化一次
        mappings.put("/hello", hello);
        mappings.put("/bye", new HelloServlet());

        // 2. 容器用线程池处理并发请求(与 Tomcat 一致)
        var pool = Executors.newFixedThreadPool(3);
        HttpServer server = null;
        try {
            server = HttpServer.create(new InetSocketAddress("127.0.0.1", 18081), 0);
            HttpServer finalServer = server;
            server.createContext("/", exchange -> {
                String path = exchange.getRequestURI().getPath();
                MiniServlet servlet = mappings.get(path);
                String body;
                if (servlet == null) {
                    body = "404 Not Found (容器找不到映射)";
                    exchange.sendResponseHeaders(404, body.getBytes(StandardCharsets.UTF_8).length);
                } else {
                    servlet.service(path, exchange.getRequestMethod());
                    body = "OK from " + path;
                    exchange.sendResponseHeaders(200, body.getBytes(StandardCharsets.UTF_8).length);
                }
                try (OutputStream os = exchange.getResponseBody()) {
                    os.write(body.getBytes(StandardCharsets.UTF_8));
                }
            });
            server.setExecutor(pool); // 请求交给线程池
            server.start();
            Thread.sleep(200);
            System.out.println("[容器] 启动完成,端口 18081\n");

            // 3. 模拟客户端并发访问
            var client = java.net.http.HttpClient.newHttpClient();
            for (String p : new String[]{"/hello", "/hello", "/bye", "/not-exist"}) {
                var resp = client.send(
                        java.net.http.HttpRequest.newBuilder(
                                java.net.URI.create("http://127.0.0.1:18081" + p)).build(),
                        java.net.http.HttpResponse.BodyHandlers.ofString());
                System.out.println("客户端 " + p + " -> " + resp.statusCode() + " " + resp.body());
            }
        } catch (Exception e) {
            System.out.println("沙箱环境可能限制端口绑定: " + e.getMessage());
        } finally {
            // 4. 容器关闭: 销毁所有 Servlet
            System.out.println("\n[容器] 准备关闭...");
            mappings.values().forEach(MiniServlet::destroy);
            if (server != null) server.stop(0);
            pool.shutdown();
        }
    }
}

import com.sun.net.httpserver.HttpServer;
import java.lang.annotation.*;
import java.lang.reflect.Method;
import java.net.InetSocketAddress;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Main {

    // ---------- 1. 定义注解(对照 Spring 的 @RestController / @GetMapping) ----------
    @Retention(RetentionPolicy.RUNTIME)
    @Target(ElementType.METHOD)
    @interface GetMapping { String value(); }

    @Retention(RetentionPolicy.RUNTIME)
    @Target(ElementType.TYPE)
    @interface RestController { }

    // ---------- 2. 控制器(对照本项目 LearningController) ----------
    @RestController
    static class UserController {
        @GetMapping("/api/users")
        public String list() {
            return "{\"code\":0,\"data\":[\"张三\",\"李四\"]}";
        }

        @GetMapping("/api/users/{id}")
        public String detail(String id) {
            return "{\"code\":0,\"data\":{\"id\":" + id + ",\"name\":\"用户" + id + "\"}}";
        }
    }

    // ---------- 3. 迷你 DispatcherServlet: 扫描注解 + 建路由表 + 分发 ----------
    static class MiniDispatcher {
        record Route(Pattern pattern, List<String> vars, Method method, Object handler) { }
        final List<Route> routes = new ArrayList<>();

        void register(Object controller) {
            if (!controller.getClass().isAnnotationPresent(RestController.class)) return;
            for (Method m : controller.getClass().getDeclaredMethods()) {
                GetMapping mapping = m.getAnnotation(GetMapping.class);
                if (mapping == null) continue;
                // 把 /api/users/{id} 编译成正则,同时记录变量名
                List<String> vars = new ArrayList<>();
                StringBuilder regexSb = new StringBuilder();
                Matcher matcher = Pattern.compile("\\{([^/]+)\\}").matcher(mapping.value());
                while (matcher.find()) {
                    vars.add(matcher.group(1));
                    matcher.appendReplacement(regexSb, "([^/]+)");
                }
                matcher.appendTail(regexSb);
                String regex = regexSb.toString();
                routes.add(new Route(Pattern.compile("^" + regex + "$"), vars, m, controller));
                System.out.println("  [路由注册] GET " + mapping.value()
                        + " -> " + controller.getClass().getSimpleName() + "#" + m.getName());
            }
        }

        String dispatch(String httpMethod, String path) {
            for (Route r : routes) {
                Matcher matcher = r.pattern().matcher(path);
                if (!matcher.matches()) continue;
                try {
                    Object[] args = new Object[r.vars().size()];
                    for (int i = 0; i < args.length; i++) args[i] = matcher.group(i + 1);
                    return (String) r.method().invoke(r.handler(), args);
                } catch (Exception e) {
                    return "{\"code\":500,\"message\":\"服务器内部错误\"}";
                }
            }
            return "{\"code\":404,\"message\":\"没有匹配的路由\"}";
        }
    }

    public static void main(String[] args) throws Exception {
        System.out.println("[启动] 扫描控制器,建立路由表:");
        MiniDispatcher dispatcher = new MiniDispatcher();
        dispatcher.register(new UserController());

        HttpServer server = null;
        try {
            server = HttpServer.create(new InetSocketAddress("127.0.0.1", 18082), 0);
            server.createContext("/", exchange -> {
                String path = exchange.getRequestURI().getPath();
                String body = dispatcher.dispatch(exchange.getRequestMethod(), path);
                byte[] bytes = body.getBytes(StandardCharsets.UTF_8);
                exchange.getResponseHeaders().set("Content-Type", "application/json; charset=utf-8");
                exchange.sendResponseHeaders(200, bytes.length);
                try (var os = exchange.getResponseBody()) { os.write(bytes); }
            });
            server.start();
            Thread.sleep(200);

            System.out.println("\n[测试] 模拟客户端请求:");
            var client = java.net.http.HttpClient.newHttpClient();
            for (String p : new String[]{"/api/users", "/api/users/42", "/api/orders"}) {
                var resp = client.send(java.net.http.HttpRequest.newBuilder(
                                java.net.URI.create("http://127.0.0.1:18082" + p)).build(),
                        java.net.http.HttpResponse.BodyHandlers.ofString());
                System.out.println("  GET " + p);
                System.out.println("    -> " + resp.body());
            }
        } catch (Exception e) {
            System.out.println("沙箱环境可能限制端口绑定: " + e.getMessage());
        } finally {
            if (server != null) server.stop(0);
        }

        System.out.println("\n这就是 Spring MVC 的核心机制:");
        System.out.println("  @GetMapping 注解 -> 扫描建路由表 -> 按路径匹配 -> 提取路径变量 -> 反射调用");
    }
}

import java.lang.annotation.*;
import java.lang.reflect.Field;
import java.util.*;

public class Main {

    // ---------- 注解(对照 Spring 的 @Component / @Autowired) ----------
    @Retention(RetentionPolicy.RUNTIME) @Target(ElementType.TYPE)
    @interface Component { }

    @Retention(RetentionPolicy.RUNTIME) @Target(ElementType.FIELD)
    @interface Autowired { }

    @Component
    static class UserRepository {
        public String findById(long id) { return "用户#" + id + " 张三"; }
    }

    @Component
    static class ScoreRepository {
        public int scoreOf(long id) { return 88; }
    }

    @Component
    static class UserService {
        @Autowired private UserRepository userRepository;
        @Autowired private ScoreRepository scoreRepository;

        public String describe(long id) {
            if (userRepository == null) return "依赖未注入!";
            return userRepository.findById(id) + ", 成绩 " + scoreRepository.scoreOf(id);
        }
    }

    // ---------- 迷你 IoC 容器 ----------
    static class MiniApplicationContext {
        private final Map<Class<?>, Object> beans = new HashMap<>();

        MiniApplicationContext(Class<?>... candidates) {
            // 第 1 步: 扫描 -> 实例化
            for (Class<?> c : candidates) {
                if (c.isAnnotationPresent(Component.class)) {
                    try {
                        Object instance = c.getDeclaredConstructor().newInstance();
                        beans.put(c, instance);
                        System.out.println("  [容器] 实例化 " + c.getSimpleName());
                    } catch (Exception e) {
                        throw new RuntimeException(e);
                    }
                }
            }
            // 第 2 步: 注入 @Autowired 字段
            for (Object bean : beans.values()) {
                for (Field f : bean.getClass().getDeclaredFields()) {
                    if (!f.isAnnotationPresent(Autowired.class)) continue;
                    Object dependency = beans.get(f.getType());
                    if (dependency == null) {
                        throw new IllegalStateException("找不到依赖: " + f.getType().getSimpleName());
                    }
                    f.setAccessible(true);
                    try { f.set(bean, dependency); } catch (Exception e) { throw new RuntimeException(e); }
                    System.out.println("  [容器] 注入 " + bean.getClass().getSimpleName()
                            + "." + f.getName() + " <- " + dependency.getClass().getSimpleName());
                }
            }
        }

        <T> T getBean(Class<T> type) { return type.cast(beans.get(type)); }
    }

    public static void main(String[] args) {
        System.out.println("[启动] 扫描并装配 Bean:");
        MiniApplicationContext ctx = new MiniApplicationContext(
                UserRepository.class, ScoreRepository.class, UserService.class);

        System.out.println("\n[使用] 从容器取 Bean 并调用:");
        UserService service = ctx.getBean(UserService.class);
        System.out.println("  " + service.describe(1001));
        System.out.println("  " + service.describe(1002));

        System.out.println("\n[验证] 单例: 两次 getBean 是同一对象? "
                + (ctx.getBean(UserService.class) == service));

        System.out.println("\n对照 Spring: @SpringBootApplication 启动时做的就是上述过程,");
        System.out.println("只是支持了构造器注入、循环依赖、AOP 代理、作用域等更多细节");
    }
}

public class Main {

    // ---------- 依赖接口与两种实现 ----------
    interface SmsSender {
        String send(String msg);
    }
    static class RealSmsSender implements SmsSender {
        public String send(String msg) { return "真实短信已发送: " + msg; }
    }
    /** 测试替身(Mock): 不发真短信,只记录 */
    static class MockSmsSender implements SmsSender {
        String lastMessage;
        public String send(String msg) { this.lastMessage = msg; return "MOCK"; }
    }

    // ---------- 字段注入风格(对照 @Autowired 私有字段) ----------
    static class OrderServiceFieldInjection {
        // private @Autowired SmsSender smsSender;  // 无法从外部设置 -> 测试困难
        private SmsSender smsSender = new RealSmsSender(); // 只能硬编码真实实现
        public String placeOrder() { return "下单成功; " + smsSender.send("您的订单已创建"); }
    }

    // ---------- 构造器注入风格(Spring 官方推荐) ----------
    static class OrderServiceConstructorInjection {
        private final SmsSender smsSender; // final: 不可变,线程安全
        OrderServiceConstructorInjection(SmsSender smsSender) { this.smsSender = smsSender; }
        public String placeOrder() { return "下单成功; " + smsSender.send("您的订单已创建"); }
    }

    public static void main(String[] args) {
        System.out.println("--- 字段注入: 只能跑真实实现 ---");
        System.out.println("  " + new OrderServiceFieldInjection().placeOrder());
        System.out.println("  问题: 想替换成 Mock 只能改源码/用反射,单测成本高,依赖关系也不显式\n");

        System.out.println("--- 构造器注入: 生产用真实实现 ---");
        var prod = new OrderServiceConstructorInjection(new RealSmsSender());
        System.out.println("  " + prod.placeOrder());

        System.out.println("\n--- 构造器注入: 测试用 Mock(一行搞定) ---");
        MockSmsSender mock = new MockSmsSender();
        var underTest = new OrderServiceConstructorInjection(mock);
        String result = underTest.placeOrder();
        System.out.println("  调用结果: " + result);
        System.out.println("  Mock 捕获到的消息: " + mock.lastMessage);
        System.out.println("  断言: 下单后应发送通知 -> " + (mock.lastMessage.contains("订单") ? "通过 ✓" : "失败 ✗"));

        System.out.println("\n结论: 构造器注入让依赖显式化、可 final、易测试 —— 这就是官方推荐的理由");
        System.out.println("对照本项目: UserServiceTest 用容器 + 真实 SQLite 测试,也可改为构造器注入 + Mock 提速");
    }
}

import java.lang.annotation.*;
import java.lang.reflect.*;
import java.util.*;

public class Main {

    // ---------- 业务接口与实现 ----------
    interface UserService {
        String findUser(long id);
        void deleteUser(long id);
    }

    static class UserServiceImpl implements UserService {
        public String findUser(long id) { sleep(30); return "用户#" + id; }
        public void deleteUser(long id) { sleep(10); System.out.println("    删除用户 " + id + " 成功"); }
        private void sleep(int ms) {
            try { Thread.sleep(ms); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        }
    }

    // ---------- 自定义注解(对照本项目的 @OperationLog) ----------
    @Retention(RetentionPolicy.RUNTIME) @Target(ElementType.METHOD)
    @interface OperationLog { String value(); }

    /** 演示用: 带注解的接口,代理会识别并"记操作日志" */
    interface AdminService {
        @OperationLog("删除用户")
        void removeUser(long id);
        void queryUser(long id);
    }
    static class AdminServiceImpl implements AdminService {
        public void removeUser(long id) { System.out.println("    [业务] 已删除用户 " + id); }
        public void queryUser(long id) { System.out.println("    [业务] 查询用户 " + id); }
    }

    // ---------- 切面: JDK 动态代理 + InvocationHandler ----------
    @SuppressWarnings("unchecked")
    static <T> T createProxy(T target, Class<T> interfaceType) {
        return (T) Proxy.newProxyInstance(
                interfaceType.getClassLoader(),
                new Class<?>[]{interfaceType},
                (proxy, method, args) -> {
                    String methodName = method.getName();
                    // 通知 @Before: 记录操作日志注解
                    OperationLog logAnno = method.getAnnotation(OperationLog.class);
                    if (logAnno != null) {
                        System.out.println("    [操作日志] 记录: " + logAnno.value()
                                + " (参数: " + Arrays.toString(args) + ")");
                    }
                    // 通知 @Around: 计时
                    long begin = System.currentTimeMillis();
                    Object result = method.invoke(target, args);
                    long cost = System.currentTimeMillis() - begin;
                    System.out.println("    [性能监控] " + methodName + " 耗时 " + cost + "ms");
                    return result;
                });
    }

    public static void main(String[] args) {
        System.out.println("--- 场景1: 日志与耗时切面(代理 UserService) ---");
        UserService userService = createProxy(new UserServiceImpl(), UserService.class);
        System.out.println("  调用 findUser(1001): " + userService.findUser(1001));
        System.out.println("  调用 deleteUser(1002):");
        userService.deleteUser(1002);

        System.out.println("\n--- 场景2: 注解驱动的操作日志(对照本项目 @OperationLog + AOP) ---");
        AdminService adminService = createProxy(new AdminServiceImpl(), AdminService.class);
        System.out.println("  调用 removeUser(2001) [有 @OperationLog]:");
        adminService.removeUser(2001);
        System.out.println("  调用 queryUser(2001) [无注解]:");
        adminService.queryUser(2001);

        System.out.println("\n--- 验证: 代理不是原对象 ---");
        System.out.println("  " + userService.getClass().getName());
        System.out.println("  isProxy = " + Proxy.isProxyClass(userService.getClass()));

        System.out.println("\n结论: 业务代码一行没改,日志/耗时/操作记录全被'织入'——这就是 AOP 的价值");
    }
}

import java.lang.reflect.*;
import java.util.*;

public class Main {

    /** 模拟数据库: 一张账户表 */
    static final Map<String, Integer> DB = new LinkedHashMap<>();

    /** 事务管理器(简化版) */
    static class TxManager {
        /** 事务内的操作日志,回滚时据此撤销 */
        private final List<Runnable> undoLog = new ArrayList<>();
        private boolean inTransaction = false;

        void begin() {
            inTransaction = true;
            undoLog.clear();
            System.out.println("  [事务] BEGIN");
        }

        void record(String account, int oldValue) {
            undoLog.add(() -> DB.put(account, oldValue));
        }

        void commit() {
            inTransaction = false;
            undoLog.clear();
            System.out.println("  [事务] COMMIT (全部生效)");
        }

        void rollback() {
            // 逆序撤销
            for (int i = undoLog.size() - 1; i >= 0; i--) undoLog.get(i).run();
            inTransaction = false;
            System.out.println("  [事务] ROLLBACK (已撤销 " + undoLog.size() + " 步操作)");
            undoLog.clear();
        }
    }

    static final TxManager TX = new TxManager();

    /** 转账业务: 未加事务的原始逻辑 */
    static void transferRaw(String from, String to, int amount, boolean failAfterDebit) {
        int f = DB.get(from), t = DB.get(to);
        DB.put(from, f - amount);
        TX.record(from, f);
        System.out.println("    已扣款: " + from + " -" + amount);
        if (failAfterDebit) throw new IllegalStateException("模拟: 收款方账户异常");
        DB.put(to, t + amount);
        TX.record(to, t);
        System.out.println("    已入账: " + to + " +" + amount);
    }

    /** 事务代理: 对应 @Transactional 的 AOP 织入 */
    static void transferWithTx(String from, String to, int amount, boolean fail) {
        TX.begin();
        try {
            transferRaw(from, to, amount, fail);
            TX.commit();
        } catch (Exception e) {
            System.out.println("    异常: " + e.getMessage());
            TX.rollback();
        }
    }

    static void reset() { DB.clear(); DB.put("张三", 1000); DB.put("李四", 1000); }

    public static void main(String[] args) {
        System.out.println("=== 场景1: 正常转账(有事务) ===");
        reset();
        transferWithTx("张三", "李四", 100, false);
        System.out.println("  结果: " + DB);

        System.out.println("\n=== 场景2: 扣款后异常(有事务 -> 回滚) ===");
        reset();
        transferWithTx("张三", "李四", 100, true);
        System.out.println("  结果: " + DB + "  <- 张三的钱回来了,数据一致");

        System.out.println("\n=== 场景3: 同样的异常,但没有事务 ===");
        reset();
        transferRaw("张三", "李四", 100, true);
        System.out.println("  结果: " + DB + "  <- 钱凭空消失 100! 这就是必须用事务的理由");

        System.out.println("\n=== 场景4: 自调用陷阱演示 ===");
        System.out.println("  class A { public void outer() { this.inner(); } @Transactional public void inner() {...} }");
        System.out.println("  outer -> this.inner(): 不经过代理 -> 事务不生效!");
        System.out.println("  正解: 拆到另一个 Bean,或自注入后调 proxy.inner()");

        System.out.println("\n对照本项目: LearningDataSeedService 的 @Transactional(rollbackFor = Exception.class)");
        System.out.println("保证 91 个课时的导入要么全成功、要么全回滚,不会留下半截课程数据");
    }
}

import java.util.*;

public class Main {

    /** 模拟 Spring 的 @Conditional 条件评估器 */
    static class ConditionEvaluator {
        Set<String> classpath = new HashSet<>();   // 类路径上有什么(模拟)
        Set<String> existingBeans = new HashSet<>(); // 容器里已有什么 Bean

        boolean onClass(String className) { return classpath.contains(className); }
        boolean missingBean(String beanName) { return !existingBeans.contains(beanName); }
        boolean onProperty(String key, String value) { return propertyValues.getOrDefault(key, "").equals(value); }
        Map<String, String> propertyValues = new HashMap<>();
    }

    /** 模拟一个自动配置类 */
    static class DataSourceAutoConfiguration {
        String name;
        List<String> conditions = new ArrayList<>();
        Runnable action;

        DataSourceAutoConfiguration(String name) { this.name = name; }

        /** 评估所有条件,决定是否"生效" */
        boolean evaluate(ConditionEvaluator env) {
            for (String c : conditions) {
                String[] parts = c.split("=", 2);
                boolean pass = switch (parts[0]) {
                    case "onClass"     -> env.onClass(parts[1]);
                    case "missingBean" -> env.missingBean(parts[1]);
                    case "onProperty"  -> { String[] kv = parts[1].split(":"); yield env.onProperty(kv[0], kv[1]); }
                    default -> false;
                };
                System.out.printf("    条件 %-28s -> %s%n", c, pass ? "满足" : "不满足(跳过)");
                if (!pass) return false;
            }
            return true;
        }

        void apply(ConditionEvaluator env) {
            System.out.println("  [" + name + "] 条件评估:");
            if (evaluate(env)) {
                System.out.println("  ==> 自动配置生效!");
                env.existingBeans.add(name);
            } else {
                System.out.println("  ==> 不生效,跳过");
            }
        }
    }

    public static void main(String[] args) {
        System.out.println("=== 场景1: Spring Boot 默认环境(引入 starter-web) ===");
        ConditionEvaluator env = new ConditionEvaluator();
        env.classpath.addAll(List.of("org.apache.tomcat.embed.Tomcat", "com.zaxxer.hikari.HikariDataSource",
                "org.sqlite.JDBC", "org.springframework.web.servlet.DispatcherServlet"));
        env.propertyValues.put("spring.datasource.url", "jdbc:sqlite:admin.db");

        DataSourceAutoConfiguration dsAuto = new DataSourceAutoConfiguration("DataSourceAutoConfiguration");
        dsAuto.conditions.add("onClass=com.zaxxer.hikari.HikariDataSource");
        dsAuto.conditions.add("missingBean=dataSource");
        dsAuto.apply(env);
        System.out.println("  结果: 容器里现在有 " + env.existingBeans + "\n");

        System.out.println("=== 场景2: 项目自定义了数据源(SandboxDataSourceConfig) ===");
        env.existingBeans.add("dataSource"); // 自定义 @Bean 抢先注册
        System.out.println("  (模拟: 项目里已用 @Bean 声明了 dataSource)");
        dsAuto.apply(env);
        System.out.println("  结果: 自动配置退让,使用项目的自定义数据源 —— 这就是 @ConditionalOnMissingBean 的意义\n");

        System.out.println("=== 场景3: 缺少 Hikari 依赖(没引连接池) ===");
        ConditionEvaluator env2 = new ConditionEvaluator();
        env2.classpath.add("org.sqlite.JDBC"); // 只有驱动,没有连接池
        dsAuto.apply(env2);
        System.out.println("  结果: 自动配置跳过,如无自定义配置则启动失败并给出清晰报错\n");

        System.out.println("对照本项目 application.yml:");
        System.out.println("  spring.datasource.url: jdbc:sqlite:data/admin.db   <- 覆盖默认数据源");
        System.out.println("  jpa.hibernate.ddl-auto: update                      <- 覆盖建表策略");
        System.out.println("  Boot 的核心哲学: 默认开箱即用,需要时才覆盖");
    }
}

import java.util.*;

public class Main {

    // ---------- DTO 与统一响应(对照本项目 Result / LoginRequest) ----------
    record LoginRequest(String username, String password) { }

    static class Result {
        int code; String message; Object data;
        static Result ok(Object data) { return build(0, "success", data); }
        static Result fail(int code, String message) { return build(code, message, null); }
        private static Result build(int code, String message, Object data) {
            Result r = new Result(); r.code = code; r.message = message; r.data = data; return r;
        }
        public String toString() {
            return "{\"code\":" + code + ",\"message\":\"" + message
                    + "\",\"data\":" + (data == null ? "null" : "\"" + data + "\"") + "}";
        }
    }

    // ---------- 模拟业务异常与全局异常处理器 ----------
    static class BusinessException extends RuntimeException {
        BusinessException(String msg) { super(msg); }
    }

    static Result globalExceptionHandler(Exception e) {
        if (e instanceof BusinessException) return Result.fail(1001, e.getMessage());
        if (e instanceof IllegalArgumentException) return Result.fail(400, e.getMessage());
        return Result.fail(500, "服务器内部错误"); // 不泄露堆栈细节
    }

    // ---------- 模拟 Controller ----------
    static class AuthController {
        Map<String, String> users = Map.of("admin", "admin123", "user", "user123");

        Result login(LoginRequest req) {
            // 1. 参数校验(对照 @Valid)
            if (req.username() == null || req.username().isBlank())
                throw new IllegalArgumentException("用户名不能为空");
            if (req.password() == null || req.password().length() < 6)
                throw new IllegalArgumentException("密码长度不能少于 6 位");
            // 2. 业务逻辑
            if (!req.password().equals(users.get(req.username())))
                throw new BusinessException("用户名或密码错误");
            // 3. 统一响应
            return Result.ok("jwt-token-xyz");
        }
    }

    public static void main(String[] args) {
        AuthController controller = new AuthController();

        System.out.println("=== POST /api/auth/login 各种情况 ===\n");

        // 用例 1: 正常登录
        System.out.println("请求: {\"username\":\"admin\",\"password\":\"admin123\"}");
        System.out.println("响应: " + controller.login(new LoginRequest("admin", "admin123")));

        // 用例 2: 参数校验失败(空用户名)
        System.out.println("\n请求: {\"username\":\"\",\"password\":\"admin123\"}");
        try {
            controller.login(new LoginRequest("", "admin123"));
        } catch (Exception e) {
            System.out.println("响应: " + globalExceptionHandler(e));
        }

        // 用例 3: 密码太短
        System.out.println("\n请求: {\"username\":\"admin\",\"password\":\"123\"}");
        try {
            controller.login(new LoginRequest("admin", "123"));
        } catch (Exception e) {
            System.out.println("响应: " + globalExceptionHandler(e));
        }

        // 用例 4: 密码错误(业务异常)
        System.out.println("\n请求: {\"username\":\"admin\",\"password\":\"wrongpwd\"}");
        try {
            controller.login(new LoginRequest("admin", "wrongpwd"));
        } catch (Exception e) {
            System.out.println("响应: " + globalExceptionHandler(e));
        }

        System.out.println("\n=== 设计要点 ===");
        System.out.println("  1. 参数校验与业务校验分离: 前者 400,后者 1001(业务码)");
        System.out.println("  2. 所有响应同一结构,前端只判断 code");
        System.out.println("  3. 未知异常统一 500,绝不把堆栈返回给客户端");
        System.out.println("  4. 本项目对应类: AuthController / BusinessException / GlobalExceptionHandler / Result");
    }
}

import java.util.*;

public class Main {

    /** 模拟 Spring 的配置优先级(后者覆盖前者,按加载顺序) */
    static class ConfigLoader {
        Map<String, String> values = new LinkedHashMap<>();

        ConfigLoader load(String source, Map<String, String> conf) {
            System.out.println("  加载 " + source + ": " + conf);
            values.putAll(conf); // 按顺序覆盖
            return this;
        }

        String get(String key) { return values.getOrDefault(key, "<未配置>"); }
    }

    public static void main(String[] args) {
        System.out.println("=== Spring Boot 配置优先级演示(从低到高) ===\n");

        ConfigLoader config = new ConfigLoader();

        // 1. 最低: application.yml 默认值
        config.load("application.yml(默认)",
                Map.of("server.port", "8080",
                       "spring.datasource.url", "jdbc:sqlite:data/admin.db",
                       "logging.level.root", "INFO"));

        // 2. application-prod.yml(profile 差异)
        config.load("application-prod.yml",
                Map.of("logging.level.root", "WARN",
                       "spring.datasource.url", "jdbc:mysql://prod-db:3306/app"));

        // 3. 环境变量(生产注入密钥,不写进代码库)
        config.load("环境变量(SPRING_DATASOURCE_PASSWORD)",
                Map.of("spring.datasource.password", "******(来自密钥管理)"));

        // 4. 最高: 命令行参数
        config.load("命令行参数",
                Map.of("server.port", "9090"));

        System.out.println("\n=== 最终生效配置 ===");
        for (String key : new String[]{"server.port",
                "spring.datasource.url", "spring.datasource.password", "logging.level.root"}) {
            System.out.printf("  %-28s = %s%n", key, config.get(key));
        }

        System.out.println("\n=== 覆盖规则总结 ===");
        System.out.println("  命令行 > 环境变量 > application-{profile}.yml > application.yml");
        System.out.println("  实践要点:");
        System.out.println("    - 密码/密钥只放环境变量或配置中心,永不入库");
        System.out.println("    - server.port 被命令行覆盖成 9090 -> 一个 jar 多处部署");

        System.out.println("\n=== 本项目部署命令回顾 ===");
        System.out.println("  mvn clean package");
        System.out.println("  java -jar target/spring-boot-learning-1.0.0.jar");
        System.out.println("  java -jar app.jar --spring.profiles.active=prod --server.port=9090");
        System.out.println("  后台: nohup java -jar app.jar > app.log 2>&1 &");
    }
}

import java.util.*;

public class Main {

    // ---------- 单体: 一个进程内的模块调用 ----------
    static class MonolithApp {
        Map<String, Object> createOrder(String user, String item) {
            // 全部在一个 JVM 内,方法调用 = 内存跳转(纳秒级)
            String userId = userModule_validate(user);
            String stock = stockModule_lock(item);
            String pay = payModule_charge(userId);
            return Map.of("orderId", "NO-" + System.nanoTime() % 10000,
                    "user", userId, "stock", stock, "pay", pay);
        }
        String userModule_validate(String u) { return "用户[" + u + "]有效"; }
        String stockModule_lock(String i) { return "库存[" + i + "]已锁定"; }
        String payModule_charge(String u) { return "支付成功"; }
    }

    // ---------- 微服务: 同样的业务,跨网络调用 ----------
    static class MicroserviceApp {
        // 模拟一次远程调用: 序列化 -> 网络 -> 反序列化 -> 可能的超时/重试
        static String remoteCall(String service, String action) {
            try { Thread.sleep(15); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
            return service + ":" + action + " 成功";
        }

        Map<String, Object> createOrder(String user, String item) {
            System.out.println("    [网关] 接收请求,路由到订单服务");
            String userId = remoteCall("用户服务", "校验" + user);
            String stock = remoteCall("库存服务", "锁定" + item);
            String pay = remoteCall("支付服务", "扣款");
            return Map.of("orderId", "NO-" + System.nanoTime() % 10000,
                    "user", userId, "stock", stock, "pay", pay);
        }
    }

    public static void main(String[] args) {
        System.out.println("=== 单体架构: 一次下单 ===");
        long t1 = System.currentTimeMillis();
        var order1 = new MonolithApp().createOrder("张三", "iPhone");
        long single = System.currentTimeMillis() - t1;
        System.out.println("  结果: " + order1);
        System.out.println("  耗时: " + single + "ms (方法调用,几乎为 0)\n");

        System.out.println("=== 微服务架构: 同样的下单 ===");
        long t2 = System.currentTimeMillis();
        var order2 = new MicroserviceApp().createOrder("张三", "iPhone");
        long micro = System.currentTimeMillis() - t2;
        System.out.println("  结果: " + order2);
        System.out.println("  耗时: " + micro + "ms (3 次远程调用,每次 15ms 模拟网络)\n");

        System.out.println("=== 代价与收益 ===");
        System.out.println("  代价:");
        System.out.println("    - 延迟: " + single + "ms -> " + micro + "ms (网络往返)");
        System.out.println("    - 复杂度: 需要注册中心/网关/熔断/链路追踪");
        System.out.println("    - 一致性: 跨服务无法用单个数据库事务");
        System.out.println("  收益:");
        System.out.println("    - 独立发布(订单服务上线不影响用户服务)");
        System.out.println("    - 独立伸缩(支付服务扛不住时单独扩容)");
        System.out.println("    - 故障隔离(库存服务挂了,商品浏览仍可用)");
        System.out.println("\n务实建议: 先做好单体模块化,真有痛点再拆;拆晚了没事,拆早了要命");
    }
}

import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;

public class Main {

    // ---------- 1. 迷你注册中心(对照 Nacos / Eureka) ----------
    static class ServiceRegistry {
        // 服务名 -> 实例地址列表
        private final Map<String, List<String>> services = new ConcurrentHashMap<>();
        private final Map<String, Long> heartbeats = new ConcurrentHashMap<>();

        void register(String serviceName, String address) {
            services.computeIfAbsent(serviceName, k -> new CopyOnWriteArrayList<>()).add(address);
            heartbeats.put(address, System.currentTimeMillis());
            System.out.println("  [注册中心] " + serviceName + " 注册实例: " + address
                    + " (共 " + services.get(serviceName).size() + " 个实例)");
        }

        /** 心跳续约: 超时未续约的实例会被摘除 */
        void heartbeat(String address) { heartbeats.put(address, System.currentTimeMillis()); }

        List<String> discover(String serviceName) {
            List<String> list = services.getOrDefault(serviceName, List.of());
            System.out.println("  [注册中心] " + serviceName + " 被查询,返回 " + list.size() + " 个可用实例");
            return list;
        }

        void healthCheck(long timeoutMs) {
            long now = System.currentTimeMillis();
            heartbeats.forEach((addr, last) -> {
                if (now - last > timeoutMs) {
                    services.values().forEach(l -> l.remove(addr));
                    System.out.println("  [注册中心] 实例心跳超时,已摘除: " + addr);
                }
            });
        }
    }

    // ---------- 2. 客户端负载均衡(轮询,对照 Spring Cloud LoadBalancer) ----------
    static class RoundRobinLoadBalancer {
        private final AtomicInteger counter = new AtomicInteger();
        private final ServiceRegistry registry;

        RoundRobinLoadBalancer(ServiceRegistry registry) { this.registry = registry; }

        String choose(String serviceName) {
            List<String> instances = registry.discover(serviceName);
            if (instances.isEmpty()) throw new IllegalStateException("没有可用实例: " + serviceName);
            String chosen = instances.get(Math.abs(counter.getAndIncrement()) % instances.size());
            System.out.println("  [负载均衡] 轮询选中: " + chosen);
            return chosen;
        }
    }

    // ---------- 3. 迷你网关(对照 Spring Cloud Gateway) ----------
    static class Gateway {
        private final Map<String, String> routeRules = new LinkedHashMap<>(); // 路径前缀 -> 服务名
        private final RoundRobinLoadBalancer lb;
        private final Map<String, String> tokens = Map.of("valid-token-123", "admin");

        Gateway(RoundRobinLoadBalancer lb) { this.lb = lb; }

        void route(String pathPrefix, String serviceName) {
            routeRules.put(pathPrefix, serviceName);
            System.out.println("  [网关] 路由规则: " + pathPrefix + "** -> " + serviceName);
        }

        String forward(String path, String token) {
            System.out.println("\n  [网关] 收到请求: " + path);
            // 步骤1: 统一鉴权(下游服务不再各自校验)
            if (token == null || !tokens.containsKey(token)) {
                System.out.println("  [网关] 鉴权失败 -> 返回 401");
                return "401 Unauthorized";
            }
            System.out.println("  [网关] 鉴权通过,用户: " + tokens.get(token));
            // 步骤2: 匹配路由
            for (Map.Entry<String, String> e : routeRules.entrySet()) {
                if (path.startsWith(e.getKey())) {
                    System.out.println("  [网关] 匹配路由 " + e.getKey() + "** -> " + e.getValue());
                    // 步骤3: 负载均衡选实例 -> 转发
                    String instance = lb.choose(e.getValue());
                    return "200 OK (来自 " + instance + " 的响应)";
                }
            }
            System.out.println("  [网关] 无匹配路由 -> 404");
            return "404 Not Found";
        }
    }

    public static void main(String[] args) throws Exception {
        ServiceRegistry registry = new ServiceRegistry();
        RoundRobinLoadBalancer lb = new RoundRobinLoadBalancer(registry);
        Gateway gateway = new Gateway(lb);

        System.out.println("=== 1. 服务启动并注册 ===");
        registry.register("user-service", "10.0.0.1:8081");
        registry.register("user-service", "10.0.0.2:8081");
        registry.register("order-service", "10.0.0.3:8082");

        System.out.println("\n=== 2. 网关配置路由 ===");
        gateway.route("/api/user", "user-service");
        gateway.route("/api/order", "order-service");

        System.out.println("\n=== 3. 客户端请求(观察负载均衡轮询) ===");
        System.out.println("  -> " + gateway.forward("/api/user/profile", "valid-token-123"));
        System.out.println("  -> " + gateway.forward("/api/user/orders", "valid-token-123"));
        System.out.println("  -> " + gateway.forward("/api/order/create", "valid-token-123"));

        System.out.println("\n=== 4. 未携带令牌(网关统一拦截) ===");
        System.out.println("  -> " + gateway.forward("/api/user/profile", null));

        System.out.println("\n=== 5. 实例故障 -> 摘除 -> 流量自动转移 ===");
        System.out.println("  (模拟 10.0.0.1 心跳超时)");
        registry.heartbeat("10.0.0.2:8081"); // 只有 0.2 续约
        registry.healthCheck(50);
        Thread.sleep(60);
        registry.heartbeat("10.0.0.2:8081");
        System.out.println("  -> " + gateway.forward("/api/user/profile", "valid-token-123"));

        System.out.println("\n=== 组件对照表 ===");
        System.out.println("  迷你实现              生产方案");
        System.out.println("  ServiceRegistry       Nacos / Eureka");
        System.out.println("  RoundRobinLoadBalancer Spring Cloud LoadBalancer");
        System.out.println("  Gateway               Spring Cloud Gateway");
        System.out.println("  下一步可自行扩展: 熔断(Resilience4j)、配置中心、链路追踪");
    }
}
